 v53Card('ROLLING INITIALIZATION',[[`pre-roll enabled`,String(!!pr.enabled)],[`seed steps`,String(pr.steps??'n/a')],[`initial total load`,v53Fmt(pr.initialTotalLoadN,1,' N')],[`final total load`,v53Fmt(pr.finalTotalLoadN,1,' N')],[`target total load`,v53Fmt(pr.targetTotalLoadN,1,' N')],[`load closure`,v53Fmt(pr.totalLoadClosurePct,3,' %')],[`body lift`,v53Fmt((pr.bodyLiftM||0)*1000,3,' mm')],[`cache hit`,String(!!pr.cacheHit)]],pr.totalLoadClosurePct<3?'SEEDED':'CHECK'),
 v53Card('TRAJECTORY / SLIP',[[`horizon`,v53Fmt(tr.horizonS,2,' s')],[`live / no-slip yaw rate`,`${v53Fmt(tr.actualYawRateDegS,3)} / ${v53Fmt(tr.idealYawRateDegS,3)} deg/s`],[`live / no-slip radius`,`${v53Fmt(tr.actualRadiusRearM,2,' m')} / ${v53Fmt(tr.idealRadiusRearM,2,' m')}`],[`front/rear slip speed`,`${v53Fmt(tr.frontSlipSpeedMps,4)} / ${v53Fmt(tr.rearSlipSpeedMps,4)} m/s`],[`friction util F/R`,`${v53Fmt(tr.frontUtilization,4)} / ${v53Fmt(tr.rearUtilization,4)}`],[`path directions opposed`,tr.pathDirectionOpposed?'YES':'no']])
