function live(){labels();dyn.set(vals());clearTimeout(autoTimer);if(paused&&dyn.mode==='STATIC')autoTimer=setTimeout(()=>{staticBusy=true;$('mode').textContent='STATIC · resolving live controls…';setTimeout(()=>{dyn.solveStatic();staticBusy=false},0)},120)}for(let id of['vg','lg','latg','lean','fp','rp','tl','fd','rd','fs','rs','fsa','rsa','fsr','rsr','dh','speed','fb','rb','drive'])$(id).oninput=live;$('autoLean').onchange=live;$('holdSpeed').onchange=live;$('bh').oninput=labels;$('sr').oninput=labels;labels();
$('static').onclick=()=>{paused=true;dyn.set(vals());dyn.solveStatic()};$('drop').onclick=()=>{dyn.set(vals());dyn.solveStatic();dyn.startDrop(+$('dh').value);paused=false};$('bump').onclick=()=>{dyn.set(vals());if(dyn.mode==='STATIC')dyn.solveStatic();dyn.startBump(+$('bh').value,.18);paused=false};$('roll').onclick=()=>{dyn.set(vals());dyn.startRolling(+$('speed').value);paused=false};$('stopRoll').onclick=()=>{paused=true;dyn.stopRolling()};$('zeroCmd').onclick=()=>{$('fb').value=0;$('rb').value=0;$('drive').value=0;live()};$('pause').onclick=()=>{paused=!paused;$('pause').textContent=paused?'Resume':'Pause'};$('step').onclick=()=>{paused=true;dyn.step();};$('reset').onclick=()=>{paused=true;$('fb').value=0;$('rb').value=0;$('drive').value=0;labels();dyn.set(vals());dyn.solveStatic()};
window.VEHICLE_LAB_API={dyn,snapshot:()=>JSON.parse(JSON.stringify(dyn.last)),static:()=>{paused=true;return dyn.solveStatic()},drop:h=>{dyn.startDrop(h||dyn.S.dropHeight);paused=false},rolling:v=>{dyn.startRolling(v===undefined?dyn.S.roadSpeedMps:v);paused=false;return dyn.last},stopRolling:()=>{paused=true;return dyn.stopRolling()},set:q=>{dyn.set(q);return dyn.last},advance:sec=>{paused=true;let n=Math.ceil(sec/dyn.S.dt);for(let i=0;i<n;i++)dyn.step();return JSON.parse(JSON.stringify(dyn.last))},audit:()=>dyn.runAudit(),pause:()=>paused=true,resume:()=>paused=false};
